python3 -c "
import numpy as np
# Test the clean bound |g(z)-g(y)| <= (sqrt(f(z))-sqrt(f(y)))^2 and the partition argument
# numerically against a NON-constant candidate to confirm it kills them.
# Try f(x)=x + 0.1*sin(x) (g nonconstant small). Check whether original inequality holds.
def f(t): return t + 0.1*np.sin(t)
def g(t): return 0.1*np.sin(t)
bad=0
for x in np.linspace(0.1,20,40):
    for y in np.linspace(0.1,20,40):
        mid=(f(x)+y)/2
        lhs=np.sqrt((x**2+f(y)**2)/2)
        rhs=np.sqrt(x*f(y))
        if not (lhs>=mid-1e-9 and mid>=rhs-1e-9):
            bad+=1
print('f=x+0.1 sin x: violations of original =', bad, 'out of 1600')
# check clean bound violation too
viol=0
for z in np.linspace(0.1,20,40):
    for y in np.linspace(0.1,20,40):
        if abs(g(z)-g(y)) > (np.sqrt(f(z))-np.sqrt(f(y)))**2 + 1e-9:
            viol+=1
print('clean bound violations =', viol)
"

